using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public static async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location (e.g. 47.6)")] double latitude,
        [Description("Longitude of the location (e.g. -122.3)")] double longitude)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);
        var current = doc.RootElement.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public static async Task<string> GeocodeCityName(
        IHttpClientFactory httpClientFactory,
        [Description("City name to look up (e.g. Seattle)")] string cityName)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(cityName)}&count=1";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        if (!doc.RootElement.TryGetProperty("results", out var results)
            || results.GetArrayLength() == 0)
        {
            return $"No results found for '{cityName}'.";
        }

        var first = results[0];
        var name = first.GetProperty("name").GetString();
        var lat = first.GetProperty("latitude").GetDouble();
        var lon = first.GetProperty("longitude").GetDouble();
        var country = first.GetProperty("country").GetString();

        return $"{name}, {country} — lat: {lat}, lon: {lon}";
    }
}

